INSERT INTO `wp_comments` VALUES (1,1,'A WordPress Commenter','wapuu@wordpress.example','https://wordpress.org/','','2026-10-02 02:09:30','2026-10-02 02:09:30','Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.',0,'1','','comment',0,0),(2,104,'WooCommerce','woocommerce@noreply.com','','','2026-10-02 06:00:55','2026-10-02 06:00:55','Test order for screenshot Trạng thái đơn hàng đã được chuyển từ Chờ thanh toán sang Đã hoàn thành.',0,'1','WooCommerce','order_note',0,0);
